def check_qg3(n):
    s = Solver()
    X = [[Int(f'x{i}{j}') for j in range(n)] for i in range(n)]

    for i in range(n):
        for j in range(n):
            s.add(And(X[i][j] >= 0, X[i][j] < n))

    for i in range(n):
        s.add(X[i][i] == i)

    for i in range(n):
        s.add(Distinct(X[i]))
        s.add(Distinct([X[k][i] for k in range(n)]))

    for i in range(n):
        for j in range(n):
            for v in range(n):
                for w in range(n):
                    s.add(Implies(And(X[i][j] == v, X[j][i] == w), X[v][w] == i))

    res = s.check()
    return str(res)

